mapper.update:
UPDATE ${msg_table}
SET MESSAGE_STATUS_CD = '01',
	INTENAL_MESSAGE = '${group_no}',
	MOD_DT = SYSTIMESTAMP,
	MOD_ID = #{mod_id}
WHERE ROWID IN (
	SELECT ROWID
	FROM ${msg_table}
	WHERE SEND_TYPE_CD = '${msg_type}'
	  AND MESSAGE_STATUS_CD = '00'
	  AND (SEND_EXPECTED_DT < TO_CHAR(SYSDATE, 'YYYYMMDD')
		OR (SEND_EXPECTED_DT = TO_CHAR(SYSDATE, 'YYYYMMDD') AND SEND_EXPECTED_TIME <= TO_CHAR(SYSDATE, 'HH24MISS'))
		) ORDER BY ETRS_MTCD, REG_TYPE_CD , SEND_EXPECTED_DT, SEND_EXPECTED_TIME
	FETCH FIRST 500 ROWS ONLY
)

update ${msg_table}
set MESSAGE_STATUS_CD = '02',
	SEND_DT = SYSTIMESTAMP,
	MOD_DT = SYSTIMESTAMP,
	MOD_ID = #{mod_id}
where INTENAL_MESSAGE = '${group_no}'

update ${main_table}
set MESSAGE_STATUS_CD = '02',
	SEND_DT = SYSTIMESTAMP,
	MOD_DT = SYSTIMESTAMP,
	MOD_ID = #{mod_id}
where MESSAGE_MST_NO IN (${strmsgid})

update ${msg_table}
set MESSAGE_STATUS_CD = '00',
	INTENAL_MESSAGE = NULL,
	MOD_DT = SYSTIMESTAMP,
	MOD_ID = #{mod_id}
where INTENAL_MESSAGE = '${group_no}'
